SourceCode.Declaration:
/// <summary>
/// Base class for PricingAttribute table <c>DlvMode</c>
/// </summary>
internal abstract class GUPPricingAttributeDlvMode extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
protected DlvMode getTableRecord(Common _pricingObject)
{
    DlvMode dlvMode;

    if (_pricingObject is SalesTable)
    {
        SalesTable salesTable = _pricingObject as SalesTable;

        if (salesTable)
        {
            dlvMode = DlvMode::find(salesTable.DlvMode);
        }
    }
    else if (_pricingObject is SalesLine)
    {
        SalesLine salesLine = _pricingObject as SalesLine;

        if (salesLine)
        {
            dlvMode = DlvMode::find(salesLine.DlvMode);
        }
    }

    return dlvMode;
}
